#pragma once
#include <cstddef>
#include <cstdint>

namespace jjffe {

// The port storage bound to an ASM DATA_ label (src/core/asm_label_table.inc,
// generated by tools/gen_asm_label_table.py). addr == 0: the port has no storage
// for the label. object names the port object the storage lives in: the label
// itself for an independent static, or the block it aliases into.
struct AsmLabelStorage {
    const char*    label;
    std::uintptr_t addr;
    std::size_t    size;
    const char*    object;
};

const AsmLabelStorage* AsmLabelStorageTable(std::size_t* count);

// The same binding for every docs/audit/logic_footprint.json label and the
// replay's clock pins (src/core/logic_label_table.inc): the logic replay's
// checkpoint schema (test/test_logic_replay.cpp). Reviewed kinds mark object:
// "wide:<obj>" (LP64 8-byte slots for the ASM's 4-byte ones), "@blob" (addr is
// an offset into the loaded data blob), "inline" (addr 0: implemented as code).
const AsmLabelStorage* LogicLabelStorageTable(std::size_t* count);

// Address-base sites no scenario reaches (test/test_address_base.cpp): for a
// table / string base, addr is the address the site reads from (size 0); for
// storage, addr and size are the port storage the site reads or writes.
const AsmLabelStorage* AddressBaseProbeTable(std::size_t* count);

// Storage outside the span DATA_008804..+0x556c that the ASM call oracle's probes
// read or watch (test/test_asm_call_oracle.cpp); span labels resolve by their ASM
// offset there.
const AsmLabelStorage* OracleLabelStorageTable(std::size_t* count);

} // namespace jjffe
